L000726	
L000727	
L000728	\subsection{Hamiltonian model}
L000729	
L000730	\subsubsection{Hamiltonian model and reflection spectrum under a Floquet drive}
L000731	In the lab frame, the system Hamiltonian is
L000732	\begin{equation}
L000733		\oph_S(t) = \sum_{n=1}^N \omega_n \opad_n \opa_n + 2 \cos (\Omega t) \sum_{n=1}^{N-1} (g_n\opad_n \opa_{n+1} + h.c.) .
L000734	\end{equation}
L000735	We assume the system-bath coupling is described by
L000736	\begin{equation}
L000737		\oph_{int} = i \sqrt{\frac{\gamma}{2\pi}} \int_{-\infty}^{\infty} d \omega (\opad(\omega) \opc + \opa(\omega) \opcd) ,
L000738	\end{equation}
L000739	where $\opc = \sum_n \sqrt{\frac{\kappa_{e,n}}{\gamma}} \opa_n$ is the system operator that couples to the external drive line with coupling rate $\gamma$.
L000740	
L000741	The Langevin equations are
L000742	\begin{equation}
L000743		\ddt \opa_n = -i [\opa_n, \oph_S(t)] - \frac{\kappa_{i,n}}{2} \opa_n - \frac{1}{2} \sum_m \sqrt{\kappa_{e,n} \kappa_{e,m}} \opa_m - \sqrt{\kappa_{e,n}} \opa_{in} (t) ,
L000744	\end{equation}
L000745	and the output field is
L000746	\begin{equation}
L000747		\opa_{out} (t) = \opa_{in} (t) + \sum_n \sqrt{\kappa_{e,n}} \opa_n (t) .
L000748	\end{equation}
L000749	To derive the reflection spectrum, we can write the Langevin equation in the matrix form
L000750	\begin{equation}
L000751		\ddt \begin{pmatrix} \opa_1 \\ \vdots \\ \opa_N \end{pmatrix} = -i M(t) \begin{pmatrix} \opa_1 \\ \vdots \\ \opa_N \end{pmatrix} -
L000752		\begin{pmatrix} \sqrt{\kappa_{e,1}} \\ \vdots \\ \sqrt{\kappa_{e,N}} \end{pmatrix} \opa_{in} (t) ,
L000753	\end{equation}
L000754	where $M(t) = H(t) - i \frac{K}{2}$ and
L000755	\begin{equation}
L000756		H(t) = \begin{pmatrix} \omega_1 & & 0 \\ & \ddots & \\ 0 & & \omega_N \end{pmatrix} + 2 \cos (\Omega t)
L000757		\begin{pmatrix}
L000758			0 & g_1 & & & \\
L000759			g_1 & 0 & g_2 & \\
L000760			& g_2 & 0 & g_3 \\
L000761			& & \ddots & \ddots & \ddots \\
L000762			& & & g_{N-2} & 0 & g_{N-1} \\
L000763			& & & & g_{N-1} & 0
L000764		\end{pmatrix}
L000765	\end{equation}
L000766	and
L000767	\begin{equation}
L000768		K = \begin{pmatrix} \kappa_{i,1} & & 0 \\ & \ddots & \\ 0 & & \kappa_{i,N} \end{pmatrix} +
L000769		\begin{pmatrix}
L000770			\sqrt{\kappa_{e,1} \kappa_{e,1}} & \cdots & \sqrt{\kappa_{e,1} \kappa_{e,N}} \\
L000771			\vdots &  & \vdots \\
L000772			\sqrt{\kappa_{e,N} \kappa_{e,1}} & \cdots & \sqrt{\kappa_{e,N} \kappa_{e,N}}
L000773		\end{pmatrix} .
L000774	\end{equation}
L000775	
L000776	From the Fourier expansion
L000777	\begin{equation}
L000778		M(t) = M_0 + M_1 e^{i\Omega t} + M_{-1} e^{-i\Omega t} ,
L000779	\end{equation}
L000780	we can write the Langevin equations in the frequency domain as
L000781	\begin{equation}
L000782		-i\omega \bm{a} (\omega) = -i \sum_{k=-1}^{1} M_k \bm{a} (\omega + k \Omega) -
L000783		\begin{pmatrix} \sqrt{\kappa_{e,1}} \\ \vdots \\ \sqrt{\kappa_{e,N}} \end{pmatrix} \opa_{in} (\omega) .
L000784	\end{equation}
L000785	where $\bm{a} = (\opa_1,...,\opa_n)$.
L000786	
L000787	We can truncate the Langevin equations to the $k$th order, which gives
L000788	\begin{equation}
L000789		G (\omega)
L000790		\begin{pmatrix}
L000791			\bm{a} (\omega - k\Omega) \\
L000792			\vdots \\
L000793			\bm{a} (\omega) \\
L000794			\vdots \\
L000795			\bm{a} (\omega + k\Omega)
L000796		\end{pmatrix}
L000797		= -\begin{pmatrix}
L000798			\bm{0} \\
L000799			\vdots \\
L000800			\sqrt{\mathbf{K}_e} \\
L000801			\vdots \\
L000802			\bm{0}
L000803		\end{pmatrix}
L000804		\opa_{in} (\omega) ,
L000805	\end{equation}
L000806	where
L000807	\begin{equation}
L000808		G (\omega) =
L000809		\begin{pmatrix}
L000810			D_{\omega-k\Omega} & i M_1 & & & \\
L000811			i M_{-1} & D_{\omega-(k-1)\Omega} & i M_1 & & \\
L000812			& \ddots & \ddots & \ddots & \\
L000813			& & i M_{-1} & D_{\omega+(k-1)\Omega} & i M_1 \\
L000814			& & & i M_{-1} & D_{\omega+k\Omega}
L000815		\end{pmatrix}
L000816	\end{equation}
L000817	with $D_\omega = -i (\omega I_n - M_0)$, and $\mathbf{K}_e = (\kappa_{e,1},...,\kappa_{e,N})^T$. The reflection coefficient is therefore
L000818	\begin{equation}
L000819		S(\omega) = 1 - \sqrt{\mathbf{K}_e^T} \left[ G(\omega)^{-1}  \right]_{[kN:(k+1)N, kN:(k+1)N]} \sqrt{\mathbf{K}_e} .
L000820	\end{equation}
L000821	
L000822	
L000823	\subsubsection{Simulation of Bloch oscillation based on the Hamiltonian model}
L000824	In the lab frame, we have
L000825	\begin{equation}
L000826		\oph = \sum_{n=-\infty}^\infty \omega_n \opad_n \opa_n + 2 \cos (\Omega t) \sum_n (g_n \opad_n \opa_{n+1} + h.c.) .
L000827	\end{equation}
L000828	In the rotating frame of $\opa_n = \opb_n e^{-i(\omega_0+n\Omega) t}$, we have
L000829	\begin{equation}
L000830		\oph = \sum_{n=-\infty}^\infty \Delta_n \opbd_n \opb_n + \sum_n (g_n \opbd_n \opb_{n+1} + h.c.) ,
L000831	\end{equation}
L000832	where $\Delta_n = \omega_n - \omega_0 - n\Omega$.
L000833	
L000834	At time $t=0$, prepare initial state $\ket{\Psi(t=0)} = \cdots \ket{\beta_{n-1}} \otimes \ket{\beta_n} \otimes \ket{\beta_{n+1}} \cdots$ and denote $\bm{\beta}(0)$ as the vector of coherent-state amplitudes
L000835	\begin{equation}
L000836		\bm{\beta}(0) = \begin{pmatrix} \vdots \\ \beta_{n-1} \\ \beta_n \\ \beta_{n+1} \\ \vdots \end{pmatrix} .
L000837	\end{equation}
L000838	At time $t > 0$, the coherent-state amplitudes are given by
L000839	\begin{equation}
L000840		\bm{\beta} (t) = e^{-i(H-i\frac{K}{2})t} \bm{\beta} (0) ,
L000841	\end{equation}
L000842	where $K=\text{diag}(\cdots, \kappa_n = \kappa_{e,n}+\kappa_{i,n}, \cdots)^T$ includes the total loss rates of all modes. Using the input-output relation, we get the time-domain output field in the lab frame
L000843	\begin{equation}
L000844		S_{out} (t) = \sum_n \sqrt{\kappa_{e,n}} \beta_n(t) e^{-i(\omega_0+n\Omega) t} .
L000845	\end{equation}
L000846	The spectrum of the output field is
L000847	\begin{equation}
L000848		S_{out} (\omega) = i \sum_n \sqrt{\kappa_{e,n}} \beta_n(\omega - \omega_0 - n\Omega) ,
L000849	\end{equation}
L000850	where
L000851	\begin{equation}
L000852		\bm{\beta} (\omega) = \left( H - i\frac{K}{2} - \omega I \right)^{-1} \bm{\beta} (0) .
L000853	\end{equation}
L000854	
L000855	
L000856	
L000857	\subsubsection{Effective onsite potential in the synthetic lattice}
L000858	
L000859	
L000860	The nonlinear spacing between modes influences the system dynamics. Consider a frequency-modulated magnon system described by
L000861	\begin{equation}
L000862	H = \sum_n g_n a_n^\dagger a_{n+1} e^{i(\omega_{n+1}-\omega_n-\Omega)t} + a_{n+1}^\dagger a_n e^{-i(\omega_{n+1}-\omega_n-\Omega)t}.
L000863	\end{equation}
L000864	
L000865	Applying the gauge transformation
L000866	\begin{equation}
L000867	a_n(t) = e^{-i(\omega_n - n\Omega)t} \tilde{a}_n(t),
L000868	\end{equation}
L000869	the Hamiltonian becomes time-independent,
L000870	\begin{equation}
L000871	\tilde{H} = \sum_n g_n \tilde{a}_n^\dagger \tilde{a}_{n+1} + \text{h.c.} + \sum_n V_n \tilde{a}_n^\dagger \tilde{a}_n,
L000872	\end{equation}
L000873	with the effective onsite potential
L000874	\begin{equation}
L000875	V_n = n\Omega - \omega_n.
L000876	\end{equation}
L000877	
L000878	The potential gradient between neighboring sites,
L000879	\begin{equation}
L000880	\Delta_n = V_n - V_{n-1} = \Omega - (\omega_n - \omega_{n-1}),
L000881	\end{equation}
L000882	acts as an effective static electric field in the synthetic frequency lattice. When the gradient $\Delta_n$ is approximately uniform, the system supports Bloch oscillations along the synthetic frequency dimension. When focusing on a given mode $n$ and its nearest neighbors (which is the case in our experimental system), Bloch oscillations can be approximately achieved by enforcing $|\Delta_n| = |\Delta_{n-1}|$, which yields the modulation frequency
L000883	\begin{equation}
L000884	\Omega_n = \frac{\omega_{n+1} - \omega_{n-1}}{2}.
L000885	\end{equation}
L000886	
L000887	In contrast, for the full synthetic lattice with a linearly decreasing mode spacing $\omega_{n+1} - \omega_n = \Delta_0 - \beta n$, the effective potential $V_n = \omega_n - n\Omega$ gives rise to a position-dependent onsite gradient
L000888	\begin{equation}
L000889	V_{n+1} - V_n = \Delta_0 - \Omega - \beta n,
L000890	\end{equation}
L000891	resulting in a nonuniform force and consequently more complex dynamical evolution, which is beyond the scope of this work and will be studied in the future.
L000892	
